function goHeroSlide(i) {
  hIdx = (i + heroData.length) % heroData.length;
  document.getElementById('hero-slides').style.transform = `translateX(-${hIdx * 100}%)`;
  document.querySelectorAll('.hero-dot').forEach((d, j) => d.classList.toggle('active', j === hIdx));
}
function slideHero(d) { clearTimeout(hTimer); goHeroSlide(hIdx + d); startHeroAuto(); }
function startHeroAuto() { clearTimeout(hTimer); hTimer = setTimeout(() => { goHeroSlide(hIdx + 1); startHeroAuto(); }, 4000); }

// PRODUCT CARD
function renderCard(p, container) {
  const inWish = wishlist.includes(p.id);
  const price = p.priceLabel || `₹${p.price?.toLocaleString('en-IN')}`;
  const card = document.createElement('div');
  card.className = 'product-card fade-up';
  card.innerHTML = `
    <div class="product-card-img">
      ${p.badge ? `<span class="product-badge">${p.badge}</span>` : ''}
      <button class="wishlist-btn ${inWish ? 'active' : ''}" onclick="toggleWishlist('${p.id}',this)">
        <svg width="13" height="13" fill="${inWish ? '#e63329' : 'none'}" stroke="${inWish ? '#e63329' : '#aaa'}" stroke-width="2" viewBox="0 0 24 24"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>
      </button>
      ${p.images && p.images.length ? `<img src="${p.images[0]}" alt="${p.name}" class="product-card-real-img">` : `<span style="font-size:3rem;position:relative;z-index:1;"></span>`}
    </div>
    <div class="product-card-body">
      <div class="product-cat">${p.category}</div>
      <div class="product-name">${p.name}</div>
      <div class="product-price-row">
        <div class="product-price">${price}</div>
        <button class="add-cart-btn" onclick="addToCart('${p.id}')">
          <svg width="11" height="11" fill="none" stroke="currentColor" stroke-width="2.5" viewBox="0 0 24 24"><path d="M12 5v14M5 12h14"/></svg> Add
        </button>
      </div>
    </div>`;
  card.onclick = (e) => {
    if (!e.target.closest('.add-cart-btn')) {
      openProduct(p.id);
    }
  };
  container.appendChild(card);
}

function renderTopProducts(f = 'all') {
  const g = document.getElementById('top-products-grid'); g.innerHTML = '';
  (f === 'all' ? products : products.filter(p => p.category === f)).slice(0, 6).forEach(p => renderCard(p, g));
}
function renderAllProducts(f = 'all') {
  const g = document.getElementById('all-products-grid'); g.innerHTML = '';
  const list = f === 'all' ? products : products.filter(p => p.category === f);
  document.getElementById('all-count').textContent = `Showing ${list.length} product${list.length !== 1 ? 's' : ''}${f !== 'all' ? ' in ' + f : ''}`;
  list.forEach(p => renderCard(p, g));
}
function filterHome(cat, el) { document.querySelectorAll('#home-cats .cat-pill').forEach(c => c.classList.remove('active')); if (el) el.classList.add('active'); renderTopProducts(cat); }
function filterAll(cat, el) { currentFilter = cat; document.querySelectorAll('.filter-bar .filter-chip').forEach(c => c.classList.remove('active')); if (el) el.classList.add('active'); renderAllProducts(cat); }

// PRODUCT DETAIL
