  const inWish = wishlist.includes(p.id);
  const price = p.priceLabel || `₹${p.price?.toLocaleString('en-IN')}`;
  document.getElementById('product-detail-content').innerHTML = `
    <button class="back-btn" id="pd-back"><svg width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M19 12H5M12 19l-7-7 7-7"/></svg> Back</button>
    <div class="product-detail-grid">
      <div>
        <div class="pd-img-container">
          ${p.badge ? `<span class="pd-tag">${p.badge}</span>` : ''}
          ${p.images && p.images.length ? `
            <div class="pd-img" onmousemove="zoomImage(event, this)" onmouseleave="resetZoom(this)">
              <img id="pd-main-img" src="${p.images[0]}" alt="${p.name}">
              ${p.images.length > 1 ? `
              <div class="pd-carousel-nav">
                <button class="pd-nav-btn prev" onclick="changePdImage(-1, '${p.images.join(',')}')"><svg width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M15 18l-6-6 6-6"/></svg></button>
                <button class="pd-nav-btn next" onclick="changePdImage(1, '${p.images.join(',')}')"><svg width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M9 18l6-6-6-6"/></svg></button>
              </div>
              ` : ''}
            </div>
            ${p.images.length > 1 ? `
            <div class="pd-thumbnails">
              ${p.images.map((img, i) => `<img src="${img}" class="pd-thumb ${i === 0 ? 'active' : ''}" onclick="setPdMainImage('${img}', this)">`).join('')}
            </div>
            ` : ''}
          ` : `
            <div class="pd-img"></div>
          `}
        </div>
      </div>
      <div>
        <div class="pd-cat">${p.category}</div>
        <h1 class="pd-name">${p.name}</h1>
        <div class="pd-price">${price} <small>incl. taxes</small></div>
        <div class="pd-desc">${p.desc}</div>
        <div class="pd-actions">
          <button class="btn-wa" onclick="openWhatsApp('${p.name}')">
            ${WA_SVG} Order on WhatsApp
          </button>
          <button class="btn-wish ${inWish ? 'active' : ''}" id="dw-btn" onclick="toggleWishlistDetail('${p.id}',this)">
            <svg width="13" height="13" fill="${inWish ? '#e63329' : 'none'}" stroke="${inWish ? '#e63329' : 'currentColor'}" stroke-width="2" viewBox="0 0 24 24"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>
            ${inWish ? 'Wishlisted' : 'Wishlist'}
          </button>
        </div>
        <div style="margin-top:14px;">
          <button class="btn-primary" onclick="addToCart('${p.id}')" style="width:100%;justify-content:center;">
            <svg width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.5" viewBox="0 0 24 24"><path d="M6 2 3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z"/><line x1="3" y1="6" x2="21" y2="6"/><path d="M16 10a4 4 0 0 1-8 0"/></svg>
            Add to Cart
          </button>
        </div>
        <div class="pd-specs">
          ${p.specs.map(([k, v]) => `<div class="spec-row"><span class="spec-key">${k}</span><span class="spec-val">${v}</span></div>`).join('')}
        </div>
      </div>
    </div>`;
  document.getElementById('pd-back').onclick = () => showPage('all-products');
